class Solution {
public:
    int numberOfChild(int n, int k) {
        int pos = 0, d = 1;
        for (int i = 0; i < k; i++) {
            pos += d;
            if (pos == 0 || pos == n - 1) d = -d;
        }
        return pos;
    }
};

